items.referenceSolution:
#include <iostream>
using namespace std;

class FishBox {
    int* p;
public:
    FishBox(int v) { p = new int(v); }
    FishBox(const FishBox& other) { p = new int(*other.p); }
    ~FishBox() { delete p; }

    FishBox& operator=(const FishBox& other) {
        *p = *other.p;
        return *this;
    }

    int get() const { return *p; }
    void set(int v) { *p = v; }
};

int main() {
    int x = 0;
    int y = 0;
    cin >> x >> y;

    FishBox a(x);
    FishBox b(y);
    b = a;
    a.set(40);
    cout << "a 那一格现在是 " << a.get() << " 条" << endl;
    cout << "b 那一格现在是 " << b.get() << " 条" << endl;
    return 0;
}

