#include <iostream>
using namespace std;

class FishBox {
    int* p;
public:
    FishBox(int v) {
        p = new int(v);
        cout << "租下一格仓库，放进 " << *p << " 条" << endl;
    }
    FishBox(const FishBox& other) {
        p = new int(*other.p);
        cout << "另租一格，搬进 " << *p << " 条" << endl;
    }
    ~FishBox() {
        cout << "归还这一格仓库" << endl;
        delete p;
    }
    int get() const { return *p; }
};

void show(FishBox b) {
    cout << "小橘 的盒子里 " << b.get() << " 条" << endl;
}

int main() {
    int v = 0;
    cin >> v;

    FishBox a(v);
    show(a);
    return 0;
}

